-- Workbook-sourced May 2025 Facilities narratives. Apply after 202609160010.
insert into public.facilities_monthly_reports (reporting_period_id,civil_general_activity,mechanical,electrical)
select p.id,
jsonb_build_object('html','<ul><li>Road maintenance and landscaping around the P-M field.</li><li>Lease repair and maintenance on various leases around the P-M field, including Pad H around the tanks.</li><li>Road cleaning and repair around the P-M field.</li><li>Clean contamination at M30a, 1357, Ecopit 8 and well site 2182.</li><li>Thermal desorption unit commissioning: completing the fire suppression system civil work.</li><li>Connect well 6081 with tank and flow line.</li><li>Production cellar at thermal well 6111/N29a and at well 6189/M37a.</li><li>Prepare the basement for tanks at M37a for the corrosion inhibitor project.</li><li>Digging canal to connect the Ningbo pump with injection well I28a.</li></ul>'),
jsonb_build_object('html','<p>Pipelines and other mechanical works.</p><ul><li>Repair the corroded section near M30c and well 719P.</li><li>Tie in well 6081/O24a with tank and flow line.</li><li>Install the Ningbo pump at I28a and push piles.</li><li>Tie in thermal well 5790/M30a with tanks and flowline.</li><li>Install hydrants for the fire suppression project at the thermal desorption unit.</li><li>Supply materials for tank 300 and patch corroded spots.</li><li>Clean sand around tank 300; insulate buried insulated lines at 5790/M30a; complete tank 300/CTF sandblasting.</li></ul>'),
jsonb_build_object('html','<p>Electrical works.</p><ul><li>M37a: pushing piles for electric cable and lights (civil and electrical works).</li><li>O30c: level crushed limestone for the electrical department (civil and electrical works).</li></ul>')
from public.reporting_periods p where p.period_date='2025-05-01'
on conflict (reporting_period_id) do update set civil_general_activity=excluded.civil_general_activity,mechanical=excluded.mechanical,electrical=excluded.electrical,updated_at=now();
